import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';

const MascotasReportadasPage = () => {
  const { user } = useContext(AuthContext); // Usuario logueado
  const [mascotas, setMascotas] = useState([]);

  useEffect(() => {
    if (user?.id) {
      const fetchMascotas = async () => {
        try {
          const response = await fetch(`http://localhost:3000/api/pets?reporterId=${user.id}`);
          const data = await response.json();
          setMascotas(data);
        } catch (error) {
          console.error('Error al cargar mascotas:', error);
        }
      };

      fetchMascotas();
    }
  }, [user]);

  // El resto del componente igual
  return (
    <div style={{ padding: '20px' }}>
      <h1>Mis Mascotas Reportadas</h1>
      <p>Aquí podrás ver las mascotas que has reportado.</p>
      <div className="mascotas-container">
        {mascotas.length > 0 ? (
          mascotas.map((mascota) => (
            <div key={mascota.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', display: 'flex', alignItems: 'center' }}>
              <img src={mascota.imageUrl} alt={mascota.name} style={{ width: '100px', height: '100px', borderRadius: '8px', marginRight: '10px' }} />
              <div>
                <h2 style={{ margin: 0 }}>{mascota.name}</h2>
                <p style={{ margin: 0 }}>{mascota.location}</p>
                <button style={{ marginTop: '10px', backgroundColor: '#2f855a', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}>
                  Editar
                </button>
              </div>
            </div>
          ))
        ) : (
          <p>No has reportado ninguna mascota aún.</p>
        )}
      </div>
    </div>
  );
};

export default MascotasReportadasPage;
